<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import {Popup,showImagePreview} from 'vant'
import {label} from '@/shared/ui/presentation'
import { currentUser, httpClient } from '@/shared/http/client'
const emit=defineEmits<{changed:[]}>()
const props=defineProps<{caseId:string;status:string;assignmentVersion?:number}>()
interface Attachment {id:string;category:string;name:string;state:string;version:number;size:number;contentType:string}
interface Job {id:string;state:string;attempts:number;candidate:unknown;reviewVersion:number;confirmed:boolean}
const labels:Record<string,string>={NOTICE:'通知单',SHOP_QUOTE:'网点报价/明细',ASSESSMENT:'定损单',LOSS_ASSESSMENT:'核损单',ARRIVAL_PHOTO:'到店照',PROGRESS_PHOTO:'进度照',COMPLETION_PHOTO:'完工照'}
const cs=computed(()=>currentUser.value?.roles.includes('CUSTOMER_SERVICE'))
const staff=computed(()=>cs.value||currentUser.value?.roles.includes('ADMIN'))
const shop=computed(()=>currentUser.value?.roles.includes('REPAIR_SHOP'))
const writable=computed(()=>!['COMPLETED','CANCELLED'].includes(props.status))
const categories=computed(()=>Object.keys(labels).filter(x=>cs.value||(shop.value&&(x==='SHOP_QUOTE'||x==='ASSESSMENT'||x.endsWith('_PHOTO')))))
const rows=ref<Attachment[]>([]),page=ref(1),total=ref(0),category=ref(cs.value?'NOTICE':'ARRIVAL_PHOTO'),selected=ref<File>(),uploadKey=ref(''),replacement=ref(''),message=ref(''),busy=ref(false),reason=ref(''),notice=ref<{noticePresent:boolean;missingReason:string}>(),job=ref<Job>(),candidate=ref(''),history=ref(''),simulateFailure=ref(false),jobId=ref('')
async function call<T>(method:'get'|'post',url:string,data?:unknown,headers?:Record<string,string>){return (await httpClient.request<{data:T}>({method,url,data,headers})).data.data}
async function load(){const data=await call<{records:Attachment[];total:number}>('get',`/materials/cases/${props.caseId}?page=${page.value}&size=20`);rows.value=data.records;total.value=data.total;if(staff.value)notice.value=await call('get',`/materials/cases/${props.caseId}/notice-status`)}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action();await load()}catch(e){message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];selected.value=file;uploadKey.value=file?crypto.randomUUID():'';message.value=file?`已选择 ${file.name}，等待手动上传`:''}
async function upload(){if(!selected.value)throw Error('请选择文件');if(selected.value.size>10485760)throw Error('文件不能超过 10 MiB');if(!/\.(?:pdf|jpe?g|png)$/i.test(selected.value.name))throw Error('仅支持 PDF、JPG、JPEG 或 PNG');const body=new FormData();body.append('file',selected.value);body.append('category',category.value);if(replacement.value)body.append('replace',replacement.value);if(props.assignmentVersion)body.append('assignmentVersion',String(props.assignmentVersion));if(!uploadKey.value)uploadKey.value=crypto.randomUUID();await httpClient.post(`/materials/cases/${props.caseId}`,body,{headers:{'Content-Type':undefined,'Idempotency-Key':uploadKey.value}});replacement.value='';selected.value=undefined;uploadKey.value='';emit('changed');message.value='已真实上传并保存元数据'}
async function download(file:Attachment){const response=await httpClient.get(`/materials/${file.id}/download`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();URL.revokeObjectURL(url)}
const pdfOpen=ref(false),previewUrl=ref(''),previewName=ref('')
let previewInstance:ReturnType<typeof showImagePreview>|undefined,disposed=false
function releasePreview(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}
async function preview(file:Attachment){const response=await httpClient.get<Blob>(`/materials/${file.id}/download`,{responseType:'blob'});if(disposed)return;if(!['image/png','image/jpeg','application/pdf'].includes(response.data.type))throw Error('该文件格式不支持预览，请下载查看');releasePreview();previewUrl.value=URL.createObjectURL(response.data);previewName.value=file.name;if(response.data.type==='application/pdf')pdfOpen.value=true;else previewInstance=showImagePreview({images:[previewUrl.value],closeable:true,onClose:releasePreview})}
onUnmounted(()=>{disposed=true;previewInstance?.close();releasePreview()})
async function refreshJob(){if(!jobId.value)throw Error('请填写任务 ID');job.value=await call<Job>('get',`/ocr/${jobId.value}`);candidate.value=JSON.stringify(job.value.candidate,null,2);history.value=JSON.stringify(await call('get',`/ocr/${jobId.value}/history?page=1&size=20`),null,2)}
async function createJob(file:Attachment){job.value=await call<Job>('post','/ocr',{fileId:file.id,simulateFailure:simulateFailure.value});jobId.value=job.value.id;await refreshJob()}
async function saveCandidate(){if(!job.value)return;await call('post',`/ocr/${job.value.id}/review`,{expectedVersion:job.value.reviewVersion,candidate:JSON.parse(candidate.value)},{'Idempotency-Key':crypto.randomUUID()});await refreshJob()}
onMounted(()=>run(load))
</script>
<template><section class="materials"><p class="eyebrow">MATERIALS / 材料</p><h2>{{ shop?'上传反馈与照片':'维修照片' }}</h2><p>{{ shop?'可上传网点报价、定损单、到店照、进度照和完工照；PDF/JPG/PNG，单文件 10 MiB，每类最多 20 个有效附件。':'这里只展示服务端允许车主查看的到店、进度和完工照片。' }}</p><p role="status" aria-live="polite">{{ message }}</p><p v-if="notice">通知单：{{ notice.noticePresent?'已补齐':'缺失' }}；历史缺失原因：{{ notice.missingReason||'无' }}</p><div v-if="writable&&cs"><input v-model="reason" placeholder="通知单缺失原因"><button :disabled="busy" @click="run(async()=>{notice=await call('post',`/materials/cases/${caseId}/missing-notice`,{reason})})">记录缺失</button></div>
<div v-if="writable&&(cs||shop)" class="upload-box"><label>材料类别<select v-model="category"><option v-for="c in categories" :key="c" :value="c">{{ labels[c] }}</option></select></label><FileDropZone hint="一次1个PDF/JPG/JPEG/PNG，≤10 MiB；每类最多20个有效附件。手机可继续点击选择。" :max-bytes="10485760" :feedback="message" :disabled="busy" :busy="busy"><label class="file-field">选择文件<input type="file" accept=".pdf,.jpg,.jpeg,.png" :disabled="busy" @change="choose"></label></FileDropZone><p v-if="selected" class="selected-file">{{ selected.name }} · {{ Math.ceil(selected.size/1024) }} KiB</p><span v-if="replacement">替换 {{ replacement }}（保留旧版）</span><button :disabled="busy||!selected" @click="run(upload)">{{ busy?'上传中…':'手动上传' }}</button><button v-if="replacement" @click="replacement=''">取消替换</button><p>网络中断不会自动重放上传；文件选择和同一幂等键会保留，可手动重试。</p></div>
<ul class="material-cards"><li v-for="file in rows" :key="file.id"><div class="material-card-heading"><strong>{{ labels[file.category]||file.category }}</strong><span>{{ label(file.state) }}</span></div><p class="material-name">{{ file.name }}</p><p class="material-meta">版本 {{ file.version }} · {{ Math.ceil(file.size/1024) }} KiB</p><div class="material-actions"><button v-if="['image/png','image/jpeg','application/pdf'].includes(file.contentType)" type="button" :disabled="busy" @click="run(()=>preview(file))">预览</button><button :disabled="busy" @click="run(()=>download(file))">下载原件</button><template v-if="cs&&writable&&file.state==='ACTIVE'"><button @click="replacement=file.id;category=file.category">替换</button><button @click="run(async()=>{await call('post',`/materials/${file.id}/void`);emit('changed')})">作废</button><button v-if="!file.category.endsWith('_PHOTO')" @click="run(()=>createJob(file))">Mock OCR</button></template></div></li></ul>
<button :disabled="page===1||busy" @click="page--;run(load)">上一页</button><span>第 {{ page }} 页 / 共 {{ total }} 条</span><button :disabled="page*20>=total||busy" @click="page++;run(load)">下一页</button>
<div v-if="staff"><h3>OCR 候选复核（不写入正式业务）</h3><label v-if="cs"><input v-model="simulateFailure" type="checkbox">开发环境模拟首次失败</label><input v-model="jobId" placeholder="任务 ID"><button @click="run(refreshJob)">查询 / 刷新任务</button><template v-if="job"><p>{{ job.state }}；尝试 {{ job.attempts }} 次；版本 {{ job.reviewVersion }}；{{ job.confirmed?'人工已确认':'未确认候选' }}</p><textarea v-model="candidate" :readonly="!cs||!writable" rows="10" aria-label="OCR 候选 JSON"/><div v-if="cs&&writable"><button v-if="job.state==='FAILED'" @click="run(async()=>{await call('post',`/ocr/${job!.id}/retry`);await refreshJob()})">重试失败任务</button><template v-if="job.state==='SUCCEEDED'"><button @click="run(saveCandidate)">保存人工修正</button><button @click="run(async()=>{await call('post',`/ocr/${job!.id}/confirm`,{expectedVersion:job!.reviewVersion});await refreshJob()})">确认当前候选快照</button></template></div><details><summary>修正 / 确认历史</summary><pre>{{ history }}</pre></details></template></div><Popup v-model:show="pdfOpen" position="bottom" round closeable :style="{height:'88dvh'}" @closed="releasePreview"><section class="pdf-preview"><h3>{{ previewName }}</h3><iframe v-if="pdfOpen&&previewUrl" :src="previewUrl" :title="previewName"/><p>若浏览器无法显示PDF，可关闭后下载原件查看。</p></section></Popup></section></template>
<style scoped>.material-cards{display:grid;gap:12px}.material-cards>li{padding:16px;border:1px solid var(--color-border);border-radius:10px;background:#fff}.material-card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.material-card-heading strong{font-size:15px}.material-card-heading span{color:var(--color-text-secondary);font-size:12px}.material-name{margin:10px 0 6px;font-size:14px;line-height:1.5;overflow-wrap:anywhere}.material-meta{margin:0;font-size:12px;color:var(--color-text-secondary)}.material-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.material-actions button{margin:0}.pdf-preview{height:100%;display:flex;flex-direction:column;padding:20px 16px;box-sizing:border-box}.pdf-preview h3{font-size:16px;padding-right:32px;margin:0 0 16px;overflow-wrap:anywhere}.pdf-preview iframe{flex:1;min-height:0;width:100%;border:1px solid var(--color-border)}.pdf-preview p{font-size:12px;color:var(--color-text-secondary)}.upload-box{margin:16px 0;padding:14px;border:1px solid var(--color-border);border-radius:10px;background:#fff}.upload-box>p:last-child{color:var(--color-text-secondary);font-size:12px;line-height:1.6}.file-field input{display:block;width:100%;margin-top:8px}.selected-file{overflow-wrap:anywhere;color:var(--color-text-secondary)}ul{padding:0;list-style:none}li{margin:0;padding:14px 0;border-bottom:1px solid var(--color-border);overflow-wrap:anywhere}textarea{width:100%;box-sizing:border-box}pre{white-space:pre-wrap}</style>
